import { chromium } from "playwright";
import { createHash, randomBytes } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

const BASE_URL = "https://omnimedia-engine.vercel.app";
const RUN_ID = process.env.GITHUB_RUN_ID || String(Date.now());
const QA_EMAIL = `hello+vidgershowcase-${RUN_ID}@pivotcalls.co`;
const QA_PASSWORD = `Vg!${randomBytes(30).toString("base64url")}9a`;
const MODEL = "fal-ai/kling-video/v3/standard/text-to-video";
const OUTPUT_DIR = join(process.cwd(), "artifacts", "vidger-showcase");
const SCREENSHOT_DIR = join(OUTPUT_DIR, "screenshots");
const VIDEO_DIR = join(OUTPUT_DIR, "videos");
const STORYBOARD_DIR = join(OUTPUT_DIR, "storyboards");
const FRAME_DIR = join(OUTPUT_DIR, "frames");

const cases = [
  {
    id: "cinematic-real-movie",
    duration: "5",
    ratio: "16:9",
    prompt: "Ultra-photorealistic live-action movie shot, one continuous five-second take. A weary paramedic in a rain-darkened navy jacket steps out of an ambulance into a wet downtown street at blue hour and walks toward camera while the camera smoothly dollies backward at chest height. A second ambulance passes softly out of focus in the deep background, practical headlights reflect naturally across wet asphalt, light rain catches the street lamps, subtle breath in cold air, realistic skin pores, wet hair strands, fabric weight, eye movement, gait and foot contact. Premium large-format cinema lens, restrained shallow depth of field, natural exposure rolloff, grounded color science, physically plausible motion and reflections. Keep the same face, body proportions, uniform and ambulance geometry throughout. No beauty-filter skin, no plastic texture, no morphing, no extra fingers, no duplicated limbs, no floating feet, no warped vehicle parts, no fake lettering, no readable text, no brands, no logos, no cuts, no sudden zooms. It must look photographed on a real film set, not generated by AI."
  },
  {
    id: "premium-anime",
    duration: "5",
    ratio: "16:9",
    prompt: "Feature-film quality hand-drawn anime shot, one continuous five-second take. At sunset on a Tokyo rooftop, a young female swordswoman in a dark indigo coat stands beside a chain-link fence as a commuter train glides far below between buildings. Wind lifts a few strands of hair and the coat hem; she turns her head toward the horizon and rests one hand calmly on the sheathed sword while the camera makes a slow controlled half-orbit. Elegant 2D linework, expressive but consistent face, believable anatomy, layered painted background, cinematic sunset rim light, atmospheric city depth, restrained animation on twos with polished key poses, premium theatrical anime color grading. Preserve face design, hand anatomy, clothing folds and sword geometry. No flicker, no melting lines, no extra fingers, no limb duplication, no character morphing, no unreadable signs, no written text, no brands, no logos."
  },
  {
    id: "history-map-to-rome",
    duration: "10",
    ratio: "16:9",
    prompt: "Cinematic historical documentary sequence, one continuous ten-second visual journey with no written labels. Begin overhead on a physically real antique parchment map of the Mediterranean spread across a dark walnut research table, with hand-inked coastlines, mountains and sea texture but no readable words. A small red wax marker identifies central Italy. The camera smoothly descends and pushes toward the Italian peninsula, then the parchment geography transforms seamlessly into a realistic aerial landscape and continues down into an archaeologically grounded reconstruction of the Roman Forum around AD 117 at sunrise. End at street level moving between stone columns as merchants, citizens and a few legionaries walk naturally through the forum. Accurate Roman architecture, clothing silhouettes, materials, dust, morning light and scale; documentary realism rather than fantasy. Stable geographic zoom, coherent spatial transition, no impossible coastlines, no floating buildings, no modern objects, no text gibberish, no readable labels, no brands, no logos, no sudden cuts, no morphing people, no duplicated limbs."
  }
];

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function readJson(response) {
  const text = await response.text();
  try { return text ? JSON.parse(text) : {}; } catch { return { raw: text }; }
}

async function signUp(page) {
  const response = await page.request.post(`${BASE_URL}/api/auth`, {
    headers: { "content-type": "application/json" },
    data: { action: "signUp", email: QA_EMAIL, password: QA_PASSWORD, fullName: "Vidger Showcase QA" },
    timeout: 30_000,
  });
  const payload = await readJson(response);
  if (!response.ok() || !payload.signedIn || !payload.user?.id) {
    throw new Error(`QA signup failed: ${response.status()} ${JSON.stringify(payload)}`);
  }
  const account = { email: QA_EMAIL, userId: payload.user.id };
  await writeFile(join(OUTPUT_DIR, "qa-account.json"), JSON.stringify(account, null, 2));
  console.log(`VIDGER_SHOWCASE_ACCOUNT email=${QA_EMAIL} userId=${payload.user.id}`);
  return account;
}

function remainingCredits(payload) {
  const ws = Array.isArray(payload.workspace) ? payload.workspace[0] : payload.workspace;
  if (!ws) return 0;
  const direct = ws.credits_remaining ?? ws.remaining_credits;
  if (direct !== undefined && direct !== null) return Number(direct) || 0;
  return Math.max(0, Number(ws.credits_granted || 0) - Number(ws.credits_used || 0));
}

async function waitForCredits(page, minimum) {
  for (let attempt = 1; attempt <= 180; attempt += 1) {
    const response = await page.request.get(`${BASE_URL}/api/account`, { timeout: 30_000 });
    const payload = await readJson(response);
    if (response.ok()) {
      const credits = remainingCredits(payload);
      if (credits >= minimum) {
        console.log(`VIDGER_SHOWCASE_CREDITS_READY email=${QA_EMAIL} credits=${credits}`);
        return payload;
      }
      if (attempt % 10 === 0) console.log(`VIDGER_SHOWCASE_WAITING_FOR_CREDITS email=${QA_EMAIL} credits=${credits}`);
    }
    await sleep(4_000);
  }
  throw new Error(`QA workspace never reached ${minimum} available credits.`);
}

async function resilientStatus(page, requestId) {
  const query = new URLSearchParams({ requestId, model: MODEL });
  let last = null;
  for (let attempt = 1; attempt <= 240; attempt += 1) {
    const response = await page.request.get(`${BASE_URL}/api/providers/fal/status?${query.toString()}`, { timeout: 60_000 }).catch(() => null);
    if (response) {
      const payload = await readJson(response);
      last = { status: response.status(), payload };
      if (response.ok()) {
        if (payload.status === "COMPLETED" && payload.video?.url) return payload;
        if (payload.error) throw new Error(typeof payload.error === "string" ? payload.error : JSON.stringify(payload.error));
      }
    } else {
      last = { status: 0, payload: { error: "NETWORK_FAILURE" } };
    }
    if (attempt % 10 === 0) console.log(`VIDGER_SHOWCASE_WAIT case=${requestId} attempt=${attempt} http=${last.status} provider=${last.payload?.status || last.payload?.error || "unknown"}`);
    await sleep(4_000);
  }
  throw new Error(`Generation timed out: ${JSON.stringify(last)}`);
}

function run(command, args) {
  const result = spawnSync(command, args, { encoding: "utf8", maxBuffer: 12 * 1024 * 1024 });
  if (result.status !== 0) throw new Error(`${command} failed: ${(result.stderr || result.stdout || "").slice(-3000)}`);
  return result.stdout.trim();
}

function probe(path) {
  return JSON.parse(run("ffprobe", ["-v", "error", "-show_entries", "format=duration,size,bit_rate:format_tags=comment,encoder:stream=codec_type,codec_name,width,height,r_frame_rate,pix_fmt", "-of", "json", path]));
}

function createStoryboard(input, output) {
  run("ffmpeg", ["-hide_banner", "-loglevel", "error", "-y", "-i", input, "-vf", "fps=1,scale=480:-1,tile=5x2:padding=8:margin=8:color=0x111111", "-frames:v", "1", output]);
}

function createFrame(input, second, output) {
  run("ffmpeg", ["-hide_banner", "-loglevel", "error", "-y", "-ss", String(second), "-i", input, "-frames:v", "1", "-q:v", "2", output]);
}

async function sha256(path) {
  return createHash("sha256").update(await readFile(path)).digest("hex");
}

async function generateCase(context, testCase) {
  const page = await context.newPage();
  const result = {
    ...testCase,
    model: MODEL,
    status: "STARTED",
    requestId: null,
    generationId: null,
    providerStatus: null,
    previewScreenshot: null,
    videoFile: null,
    storyboardFile: null,
    frameFiles: [],
    probe: null,
    sha256: null,
    error: null,
    startedAt: new Date().toISOString(),
  };
  const events = [];
  page.on("console", (message) => events.push({ type: message.type(), text: message.text() }));
  page.on("pageerror", (error) => events.push({ type: "pageerror", text: error.message }));

  try {
    await page.goto(`${BASE_URL}/app`, { waitUntil: "domcontentloaded", timeout: 60_000 });
    await page.waitForSelector("[data-prompt-form]", { state: "visible", timeout: 60_000 });
    await page.waitForFunction(() => {
      const gate = document.querySelector("[data-auth-gate]");
      return !gate || gate.hidden || getComputedStyle(gate).display === "none";
    }, null, { timeout: 60_000 });

    const form = page.locator("[data-prompt-form]");
    await form.locator("textarea[name=prompt]").fill(testCase.prompt);
    await form.locator("[data-model-select]").selectOption(MODEL);
    await form.locator("[data-duration-select]").selectOption(testCase.duration);
    await form.locator("[data-ratio-select]").selectOption(testCase.ratio);
    await page.screenshot({ path: join(SCREENSHOT_DIR, `${testCase.id}-prompt.png`), fullPage: true });

    const submitResponsePromise = page.waitForResponse(
      (response) => response.url().includes("/api/providers/fal/submit") && response.request().method() === "POST",
      { timeout: 60_000 },
    );
    await form.locator("button[type=submit]").click();
    const submitResponse = await submitResponsePromise;
    const submitPayload = await readJson(submitResponse);
    if (!submitResponse.ok()) throw new Error(`Submit failed ${submitResponse.status()}: ${JSON.stringify(submitPayload)}`);
    result.requestId = submitPayload.requestId;
    result.generationId = submitPayload.generationId;
    console.log(`VIDGER_SHOWCASE_SUBMITTED case=${testCase.id} requestId=${result.requestId} duration=${testCase.duration}`);

    result.providerStatus = await resilientStatus(page, result.requestId);
    const query = new URLSearchParams({ requestId: result.requestId, model: MODEL });

    await page.goto(`${BASE_URL}/app?request=${encodeURIComponent(result.requestId)}&model=${encodeURIComponent(MODEL)}`, { waitUntil: "domcontentloaded", timeout: 60_000 });
    await page.waitForSelector("[data-prompt-result] video", { state: "visible", timeout: 120_000 });
    await page.waitForSelector("[data-prompt-result] .vidger-video-mark", { state: "visible", timeout: 60_000 });
    const video = page.locator("[data-prompt-result] video");
    await video.evaluate((node) => { node.muted = true; node.controls = true; return node.play().catch(() => null); });
    await page.waitForTimeout(1_200);
    const screenshotPath = join(SCREENSHOT_DIR, `${testCase.id}-live-playback.png`);
    await page.screenshot({ path: screenshotPath, fullPage: true });
    result.previewScreenshot = screenshotPath;

    const exportResponse = await page.request.get(`${BASE_URL}/api/providers/fal/export?${query.toString()}&branding=vidger&disposition=attachment`, { timeout: 360_000 });
    if (!exportResponse.ok()) throw new Error(`Branded export failed ${exportResponse.status()}: ${JSON.stringify(await readJson(exportResponse))}`);
    const videoPath = join(VIDEO_DIR, `${testCase.id}-vidger.mp4`);
    await writeFile(videoPath, await exportResponse.body());
    result.videoFile = videoPath;
    result.probe = probe(videoPath);
    result.sha256 = await sha256(videoPath);

    const storyboardPath = join(STORYBOARD_DIR, `${testCase.id}-storyboard.jpg`);
    createStoryboard(videoPath, storyboardPath);
    result.storyboardFile = storyboardPath;

    const duration = Number(result.probe?.format?.duration || testCase.duration || 5);
    for (const [label, second] of [["start", 0.35], ["middle", Math.max(0.5, duration / 2)], ["end", Math.max(0.5, duration - 0.5)]]) {
      const framePath = join(FRAME_DIR, `${testCase.id}-${label}.jpg`);
      createFrame(videoPath, second, framePath);
      result.frameFiles.push(framePath);
    }

    const comment = String(result.probe?.format?.tags?.comment || "");
    const videoStream = (result.probe?.streams || []).find((item) => item.codec_type === "video");
    if (!videoStream || videoStream.codec_name !== "h264" || videoStream.pix_fmt !== "yuv420p") throw new Error(`Export compatibility failed: ${JSON.stringify(videoStream || {})}`);
    if (!/Branded by Vidger/i.test(comment)) throw new Error(`Vidger branding metadata missing: ${comment}`);

    result.status = "COMPLETED";
    console.log(`VIDGER_SHOWCASE_COMPLETED case=${testCase.id} requestId=${result.requestId} bytes=${result.probe?.format?.size || "unknown"}`);
  } catch (error) {
    result.status = "FAILED";
    result.error = error instanceof Error ? error.message : String(error);
    console.error(`VIDGER_SHOWCASE_FAILED case=${testCase.id} error=${result.error}`);
    await page.screenshot({ path: join(SCREENSHOT_DIR, `${testCase.id}-failure.png`), fullPage: true }).catch(() => null);
  } finally {
    result.finishedAt = new Date().toISOString();
    result.browserEvents = events.slice(-100);
    await writeFile(join(OUTPUT_DIR, `${testCase.id}.json`), JSON.stringify(result, null, 2));
    await page.close().catch(() => null);
  }
  return result;
}

async function main() {
  await Promise.all([
    mkdir(OUTPUT_DIR, { recursive: true }),
    mkdir(SCREENSHOT_DIR, { recursive: true }),
    mkdir(VIDEO_DIR, { recursive: true }),
    mkdir(STORYBOARD_DIR, { recursive: true }),
    mkdir(FRAME_DIR, { recursive: true }),
  ]);

  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 1050 }, acceptDownloads: true });
  const bootstrap = await context.newPage();
  let account = null;
  try {
    await bootstrap.goto(`${BASE_URL}/app`, { waitUntil: "domcontentloaded", timeout: 60_000 });
    account = await signUp(bootstrap);
    await waitForCredits(bootstrap, 40);
    await bootstrap.screenshot({ path: join(SCREENSHOT_DIR, "00-authenticated-studio.png"), fullPage: true });

    const results = await Promise.all(cases.map((testCase) => generateCase(context, testCase)));
    const summary = {
      baseUrl: BASE_URL,
      runId: RUN_ID,
      qaEmail: QA_EMAIL,
      qaUserId: account?.userId || null,
      submittedNewGenerations: results.filter((item) => item.requestId).length,
      completed: results.filter((item) => item.status === "COMPLETED").length,
      failed: results.filter((item) => item.status !== "COMPLETED").length,
      results,
    };
    await writeFile(join(OUTPUT_DIR, "showcase-summary.json"), JSON.stringify(summary, null, 2));
    if (summary.completed !== cases.length) process.exitCode = 1;
  } finally {
    await bootstrap.close().catch(() => null);
    await context.close().catch(() => null);
    await browser.close().catch(() => null);
  }
}

main().catch(async (error) => {
  await mkdir(OUTPUT_DIR, { recursive: true });
  await writeFile(join(OUTPUT_DIR, "fatal-error.txt"), error?.stack || String(error));
  console.error(error);
  process.exitCode = 1;
});
